import fs from "node:fs/promises";
import path from "node:path";

// Attachments live outside the public directory and are only served through
// an authorized API route. Never place uploaded files under /public.
const STORAGE_DIR = path.join(process.cwd(), "storage", "attachments");

export function getStorageDir() {
  return STORAGE_DIR;
}

export function getStorageFilePath(storagePath) {
  // storagePath is an opaque UUID generated by the server; still guard
  // against traversal by resolving and verifying containment.
  const resolved = path.resolve(STORAGE_DIR, storagePath);
  if (!resolved.startsWith(path.resolve(STORAGE_DIR) + path.sep)) {
    throw new Error("Invalid storage path.");
  }
  return resolved;
}

export async function ensureStorageDir() {
  await fs.mkdir(STORAGE_DIR, { recursive: true });
}

export async function saveAttachmentFile(storagePath, buffer) {
  await ensureStorageDir();
  await fs.writeFile(getStorageFilePath(storagePath), buffer, { flag: "wx" });
}

export async function readAttachmentFile(storagePath) {
  return fs.readFile(getStorageFilePath(storagePath));
}

export async function deleteAttachmentFile(storagePath) {
  try {
    await fs.unlink(getStorageFilePath(storagePath));
  } catch {
    // Missing file is acceptable; metadata deletion still proceeds.
  }
}
